/// <summary>
/// Class to handle copying of fulfilment profiles.
/// </summary>
public class METCopyFulfilmentStrategy
{
}

Method.Source:
/// <summary>
/// Create a new fulfilment profile by copying the provided source profile.
/// Preserves rule sequence and copies legal entities and staged conditions.
/// Returns the newly created profile record (empty on failure).
/// </summary>
public static void copy(METFulfilmentProfile _srcProfile)
{
    METFulfilmentProfile        newProfile;
    METFulfilmentRule           ruleBuf, newRule;
    METFulfilmentLegalEntity    legalEntityBuf, newLegalEntity;
    METFulfilmentConditionTmp   metFulfilmentConditionTmp;

    // Validate source
    if (!_srcProfile.RecId)
    {
        return;
    }

    // Create new profile (keep ProfileId and Description blank)
    ttsBegin;
    newProfile.clear();
    newProfile.ProfileId            = "";
    newProfile.Description          = "";

    newProfile.SourceProfileId      = _srcProfile.ProfileId;
    newProfile.InventLocationId     = _srcProfile.InventLocationId;
    newProfile.ConditionQueryPacked = _srcProfile.ConditionQueryPacked;
    newProfile.ApplicableProcess    = _srcProfile.ApplicableProcess;
    newProfile.insert();

    // Copy legal entities
    while select legalEntityBuf
        where legalEntityBuf.ProfileId == _srcProfile.ProfileId
    {
        newLegalEntity.clear();
        newLegalEntity.ProfileId      = newProfile.ProfileId;
        newLegalEntity.LegalEntity    = legalEntityBuf.LegalEntity;
        newLegalEntity.ProfileRefNum  = newProfile.RecId;
        newLegalEntity.insert();
    }

    // Copy rules (preserve sequence)
    while select ruleBuf
        order by ruleBuf.Sequence asc
        where ruleBuf.ProfileId == _srcProfile.ProfileId
    {
        newRule.clear();
        newRule.ProfileId     = newProfile.ProfileId;
        newRule.Type          = ruleBuf.Type;
        newRule.Apply         = ruleBuf.Apply;
        newRule.Value         = ruleBuf.Value;
        newRule.Sequence      = ruleBuf.Sequence;
        newRule.ProfileRefNum = newProfile.RecId;
        newRule.insert();
    }
    ttscommit;
}
